// Content collection for group pages generated by `bfsi-intel export`.
// The Zod schema mirrors schemas/group.schema.json (the pydantic export contract), so a
// malformed or hand-edited JSON file fails the build - a second contract check.
import { defineCollection } from 'astro:content';
import { file, glob } from 'astro/loaders';
import { z } from 'astro/zod';

const ref = z.object({
  source_name: z.string(),
  url: z.string().nullable().optional(),
  citation: z.string().nullable().optional(),
});

const tactic = z.object({
  id: z.string().regex(/^TA\d{4}$/),
  name: z.string(),
  shortname: z.string(),
  order: z.number().int(),
  url: z.string(),
});

const provenance = z.object({
  source: z.enum(['mitre-attack', 'reviewed-automap', 'curated']),
  attack_version: z.string(),
  relationship_id: z.string().nullable().optional(),
  relationship_modified: z.string().nullable().optional(),
  via_group: z.string().nullable().optional(),
  article_url: z.string().nullable().optional(),
  article_source: z.string().nullable().optional(),
  method: z.string().nullable().optional(),
  reviewed_at: z.string().nullable().optional(),
});

const groups = defineCollection({
  loader: glob({ pattern: '*.json', base: './src/content/groups' }),
  schema: z.object({
    schema_version: z.literal('1.0'),
    id: z.string(),
    slug: z.string(),
    name: z.string(),
    attack_id: z.string().nullable().optional(),
    attack_url: z.string().nullable().optional(),
    aliases: z.array(z.string()),
    country: z.string().nullable().optional(),
    motivation: z.string().nullable().optional(),
    description: z.string(),
    description_source: z.enum(['mitre-attack', 'curated']),
    description_references: z.array(ref).default([]),
    bfsi: z.object({ tier: z.number().int().min(1).max(3), reason: z.string() }),
    attack_version: z.string(),
    attack_modified: z.string(),
    stix_modified: z.string().nullable().optional(),
    last_updated: z.string(),
    tactics_present: z.array(tactic),
    attacks: z.array(
      z.object({
        id: z.string(),
        kind: z.enum(['group_general', 'attack_campaign', 'curated_incident', 'reported_activity']),
        name: z.string(),
        first_seen: z.string().nullable().optional(),
        last_seen: z.string().nullable().optional(),
        url: z.string().nullable().optional(),
        summary: z.string().nullable().optional(),
        references: z.array(ref).default([]),
      }),
    ),
    rows: z.array(
      z.object({
        attack_ref: z.string(),
        technique: z.object({
          id: z.string().regex(/^T\d{4}(\.\d{3})?$/),
          name: z.string(),
          url: z.string(),
          parent_id: z.string().nullable().optional(),
        }),
        tactics: z.array(tactic),
        description: z.string(),
        references: z.array(ref).default([]),
        provenance,
        confidence: z.enum(['high', 'medium', 'low']),
      }),
    ),
    software: z
      .array(z.object({ id: z.string(), name: z.string(), type: z.enum(['malware', 'tool']), url: z.string() }))
      .default([]),
    downloads: z.object({
      navigator_layer: z.string(),
      csv: z.string(),
      navigator_url: z.string().nullable().optional(),
    }),
    counts: z.record(z.string(), z.number()),
    notice: z.string(),
    disclaimer: z.string(),
  }),
});

// One entry per technique used on any group page (+ its parent), written by
// `bfsi-intel export` to src/data/techniques.json; mirrors schemas/techniques.schema.json.
const techniques = defineCollection({
  loader: file('src/data/techniques.json'),
  schema: z.object({
    id: z.string().regex(/^T\d{4}(\.\d{3})?$/),
    name: z.string(),
    short_name: z.string(),
    parent_id: z.string().nullable().optional(),
    tactics: z.array(tactic),
    url: z.string(),
    description: z.string(),
    attack_version: z.string(),
  }),
});

export const collections = { groups, techniques };
